% Recorded-check trigger lines of the generic compatibility checks; a dash is a line MATLAB is silent on.
ver('fixpoint');
ver('xpc');
ver('slrt');
ver('powersys');
verLessThan('distcomp', '1.0');
ver('simevents');
hereHDLMConfiguration('North America');
hereHDLMConfiguration('Western Europe');
figure('Renderer', 'painters');
figure('RendererMode', 'manual');
print('-dill', 'file.eps');
print('-adobecset', 'file.eps');
timetable(x, 'SamplingRate', 10);
optimoptions('fmincon', 'InitialHessType', 'identity');
optimoptions('fmincon', 'InitialHessMatrix', eye(3));
raytrace('NumReflections', 2);
feature('UseHG2');
feature('HGUsingMATLABClasses');
dsp.VariableIntegerDelay('DirectFeedthrough', true);
dsp.VariableFractionalDelay('DirectFeedthrough', true);
dsp.DigitalDownConverter('FilterSpecification', 'Coefficients');
comm.MemorylessNonlinearity('AMPMConversion', 1);
comm.MemorylessNonlinearity('PowerLowerLimit', 1);
comm.MemorylessNonlinearity('PowerUpperLimit', 2);
comm.MemorylessNonlinearity('Method', 'Hyperbolic tangent');
comm.MemorylessNonlinearity('Method', 'Ghorbani model');
figure('GraphicsSmoothing', 'on');
set(groot, 'DefaultFigureGraphicsSmoothing', 'off');
axes('FontSmoothing', 'off');
set(groot, 'DefaultAxesFontSmoothing', 'off');
set(groot, 'DefaultTextFontSmoothing', 'off');
set(gcf, 'InvertHardCopy', 'off');
set(groot, 'defaultFigureInvertHardCopy', 'off');
save('file.mat', 'v6');
rand('v6', 1);
license('test', 'fixpoint');
hereHDLMReader('North America');
set(gcf, 'RendererMode', 'manual');
cd resources
schema.prop('MyClass', 'prop', 'double');
set(gcf, 'SamplingRate', 100);
raytracing('LaserReturns', true);
readtable('f.txt', 'RowsPerRead', 100);
disp(struct('FilterSpecification', 1));
set(obj, 'FirstFilterCoefficients', x);
set(obj, 'FrameBasedProcessing', true);
setpref('dummy', 'UseHG2', true);
